import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';
import ThemeShowcase from '../ThemeShowcase';

const ThemeSettings = () => {
  const { theme, switchTheme, themeName } = useTheme();
  const [showFullShowcase, setShowFullShowcase] = useState(false);
  
  const themeOptions = [
    { name: 'spaceFuturistic', label: 'Space & Futuristic' },
    { name: 'darkModeNeon', label: 'Dark Neon' },
    { name: 'minimalistClean', label: 'Minimalist' },
    { name: 'natureCalmness', label: 'Nature & Calm' }
  ];
  
  return (
    <>
      {/* Animated scan line effect */}
      <motion.div 
        className="absolute top-0 left-0 w-full h-px"
        style={{
          background: `linear-gradient(90deg, transparent, ${theme.animation.nodeColor}, transparent)`
        }}
        animate={{ 
          opacity: [0.2, 0.8, 0.2],
          width: ['0%', '100%', '0%']
        }}
        transition={{ duration: 4, repeat: Infinity, delay: 0.5 }}
      />
      
      <div className="p-6 relative">
        <motion.h3 
          className={`text-xl font-bold ${theme.text.primary}`}
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          Neural Interface Theme
        </motion.h3>
        
        <motion.p 
          className={`mt-2 ${theme.text.secondary}`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          Customize your study environment to enhance focus and productivity.
        </motion.p>
        
        {/* Quick Theme Selection */}
        <div className="mt-6 grid grid-cols-2 gap-3">
          {themeOptions.map((option, index) => (
            <motion.button
              key={option.name}
              className={`p-3 rounded-lg relative overflow-hidden transition-all duration-300 ${
                themeName === option.name 
                  ? 'ring-2 ring-white/50 bg-neural-600/50' 
                  : 'bg-gray-800/50 hover:bg-gray-700/50'
              }`}
              onClick={() => switchTheme(option.name)}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 + index * 0.1 }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              {themeName === option.name && (
                <motion.div 
                  className="absolute inset-0"
                  initial={{ opacity: 0 }}
                  animate={{ 
                    opacity: 1,
                    background: [
                      `radial-gradient(circle at center, ${theme.animation.highlight}40 0%, transparent 70%)`,
                      `radial-gradient(circle at center, ${theme.animation.highlight}20 0%, transparent 50%)`
                    ]
                  }}
                  transition={{ duration: 2, repeat: Infinity, repeatType: "reverse" }}
                />
              )}
              <span className={`font-medium relative z-10 ${themeName === option.name ? theme.text.primary : theme.text.muted}`}>
                {option.label}
              </span>
            </motion.button>
          ))}
        </div>
        
        {/* View All Themes Button */}
        <motion.button
          className={`mt-6 w-full p-3 rounded-lg ${theme.button.secondary} group relative overflow-hidden`}
          onClick={() => setShowFullShowcase(prev => !prev)}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
        >
          <motion.div 
            className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent"
            animate={{ 
              x: ['-100%', '100%'] 
            }}
            transition={{ 
              duration: 1.5, 
              repeat: Infinity,
              repeatDelay: 0.5
            }}
          />
          <span className="relative z-10">
            {showFullShowcase ? 'Hide Theme Gallery' : 'Explore All Neural Themes'}
          </span>
        </motion.button>
        
        {/* Theme Showcase */}
        {showFullShowcase && (
          <motion.div
            className="mt-6"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
            <ThemeShowcase />
          </motion.div>
        )}
      </div>
    </>
  );
};

export default ThemeSettings; 