import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

/**
 * A wrapper component that adds neural network visual elements to any page
 * consistent with the dashboard neural UI
 */
const NeuralPageWrapper = ({ children, title, subtitle }) => {
  const { theme } = useTheme();
  const [neurons, setNeurons] = useState([]);
  const [connections, setConnections] = useState([]);
  const [hoverPosition, setHoverPosition] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);
  
  // Generate random neural nodes and connections
  useEffect(() => {
    // Generate neural nodes - increased for more depth
    const nodeCount = 12; // More nodes for deeper effect
    const newNeurons = Array.from({ length: nodeCount }).map((_, i) => ({
      id: i,
      x: Math.random() * 100,
      y: Math.random() * 100,
      size: Math.random() * 3 + 2,
      delay: Math.random() * 2,
      duration: Math.random() * 3 + 2,
      layer: Math.floor(Math.random() * 3) // Add depth layers (0, 1, 2)
    }));
    
    // Generate neural connections with multiple paths
    const newConnections = [];
    for (let i = 0; i < newNeurons.length; i++) {
      // Each neuron connects to multiple others for more network-like appearance
      const connections = Math.floor(Math.random() * 2) + 1; // 1-2 connections
      for (let c = 0; c < connections; c++) {
        // Connect to a random neuron
        const targetIdx = Math.floor(Math.random() * newNeurons.length);
        if (targetIdx !== i) { // Don't connect to self
          newConnections.push({
            id: `connection-${i}-${targetIdx}-${c}`,
            from: i,
            to: targetIdx,
            opacity: Math.random() * 0.3 + 0.1,
            animate: Math.random() > 0.6,
            speed: Math.random() * 2 + 2, // Variable speed
            delay: Math.random() * 3
          });
        }
      }
    }
    
    setNeurons(newNeurons);
    setConnections(newConnections);
  }, []);
  
  // Track mouse movement for interactive effects
  const handleMouseMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setHoverPosition({ x, y });
    setIsHovering(true);
  };
  
  const handleMouseLeave = () => {
    setIsHovering(false);
  };
  
  // Page transition variants
  const pageVariants = {
    initial: { 
      opacity: 0, 
      y: 20,
    },
    animate: { 
      opacity: 1, 
      y: 0,
      transition: {
        duration: 0.3,
        ease: "easeOut",
        delayChildren: 0.1,
        staggerChildren: 0.05
      }
    },
    exit: { 
      opacity: 0,
      y: -20,
      transition: {
        duration: 0.2,
        ease: "easeIn"
      }
    }
  };
  
  const itemVariants = {
    initial: { 
      opacity: 0, 
      y: 20 
    },
    animate: { 
      opacity: 1, 
      y: 0,
      transition: { 
        duration: 0.3, 
        ease: "easeOut" 
      }
    }
  };
  
  return (
    <motion.div
      className="max-w-7xl mx-auto px-1 sm:px-2 pb-16 sm:pb-24 relative"
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      {/* Neural network background */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <svg className="w-full h-full neural-network-bg" xmlns="http://www.w3.org/2000/svg">
          {/* Neural connections */}
          {connections.map((connection) => {
            const fromNode = neurons[connection.from];
            const toNode = neurons[connection.to];
            
            if (!fromNode || !toNode) return null;
            
            // Add slight curve to connections for more organic look
            const midX = (parseFloat(fromNode.x) + parseFloat(toNode.x)) / 2;
            const midY = (parseFloat(fromNode.y) + parseFloat(toNode.y)) / 2;
            const curvature = (Math.random() - 0.5) * 20; // Random curve between -10 and 10
            
            return (
              <g key={connection.id} className="neural-connection">
                {/* Base connection line with curve */}
                <path
                  d={`M ${fromNode.x}% ${fromNode.y}% Q ${midX + curvature}% ${midY + curvature}% ${toNode.x}% ${toNode.y}%`}
                  stroke="rgba(100, 200, 255, 0.15)"
                  strokeWidth={0.5}
                  strokeDasharray={connection.animate ? "5,5" : undefined}
                  fill="none"
                  style={{ 
                    opacity: connection.opacity,
                    filter: 'drop-shadow(0 0 1px rgba(100, 200, 255, 0.2))'
                  }}
                />
                
                {/* Animated pulse along connections */}
                {connection.animate && (
                  <motion.circle
                    r={2}
                    fill="rgba(128, 207, 255, 0.8)"
                    filter="url(#neural-glow)"
                    initial={{ 
                      opacity: 0,
                      pathOffset: 0
                    }}
                    animate={{ 
                      opacity: [0, 0.7, 0],
                      pathOffset: [0, 1]
                    }}
                    transition={{
                      duration: connection.speed,
                      repeat: Infinity,
                      delay: connection.delay,
                      ease: "linear"
                    }}
                    style={{
                      offsetPath: `path("M ${fromNode.x}% ${fromNode.y}% Q ${midX + curvature}% ${midY + curvature}% ${toNode.x}% ${toNode.y}%")`,
                      offsetRotate: "0deg"
                    }}
                  />
                )}
                
                {/* Interactive glow highlight when mouse is near */}
                {isHovering && (
                  <path
                    d={`M ${fromNode.x}% ${fromNode.y}% Q ${midX + curvature}% ${midY + curvature}% ${toNode.x}% ${toNode.y}%`}
                    stroke="rgba(100, 200, 255, 0.4)"
                    strokeWidth={1}
                    fill="none"
                    style={{ 
                      opacity: Math.max(0, 1 - (
                        Math.min(
                          Math.hypot(hoverPosition.x - fromNode.x, hoverPosition.y - fromNode.y),
                          Math.hypot(hoverPosition.x - toNode.x, hoverPosition.y - toNode.y)
                        ) / 20
                      )),
                      filter: 'drop-shadow(0 0 2px rgba(100, 200, 255, 0.4))'
                    }}
                  />
                )}
              </g>
            );
          })}
          
          {/* SVG filters for glow effects */}
          <defs>
            <filter id="neural-glow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="2" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          
          {/* Neural nodes with depth effect */}
          {neurons.map((neuron, idx) => (
            <motion.circle
              key={`node-${idx}`}
              cx={`${neuron.x}%`}
              cy={`${neuron.y}%`}
              r={neuron.size - (neuron.layer * 0.3)} // Smaller if in deeper layer
              fill="rgba(100, 200, 255, 0.3)"
              filter="url(#neural-glow)"
              initial={{ opacity: 0.3 - (neuron.layer * 0.1) }} // More transparent if deeper
              animate={{ 
                opacity: [
                  0.3 - (neuron.layer * 0.1), 
                  0.5 - (neuron.layer * 0.1), 
                  0.3 - (neuron.layer * 0.1)
                ],
                scale: [1, 1.1, 1]
              }}
              transition={{
                duration: neuron.duration,
                delay: neuron.delay,
                repeat: Infinity,
                repeatType: "reverse"
              }}
              style={{
                filter: isHovering && 
                  Math.hypot(hoverPosition.x - neuron.x, hoverPosition.y - neuron.y) < 15
                  ? 'drop-shadow(0 0 5px rgba(100, 200, 255, 0.8))' 
                  : 'drop-shadow(0 0 2px rgba(100, 200, 255, 0.3))'
              }}
            />
          ))}
        </svg>
      </div>
      
      {/* Header with title and subtitle */}
      {(title || subtitle) && (
        <motion.div 
          className="mb-4 sm:mb-6 relative z-10"
          variants={itemVariants}
        >
          <div className="w-full overflow-hidden rounded-xl relative">
            {/* Neural network header background with depth */}
            <div className="absolute inset-0 overflow-hidden -z-10">
              <div className="absolute inset-0 bg-gray-900/70 backdrop-blur-lg" />
              
              {/* Background neurons */}
              <div className="absolute inset-0">
                {Array.from({ length: 6 }).map((_, idx) => (
                  <motion.div
                    key={`bg-neuron-${idx}`}
                    className="absolute rounded-full bg-neural-400/10"
                    style={{
                      width: `${Math.random() * 6 + 4}px`,
                      height: `${Math.random() * 6 + 4}px`,
                      left: `${Math.random() * 100}%`,
                      top: `${Math.random() * 100}%`,
                      filter: 'blur(1px)'
                    }}
                    animate={{
                      opacity: [0.3, 0.6, 0.3]
                    }}
                    transition={{
                      duration: Math.random() * 3 + 2,
                      repeat: Infinity,
                      delay: Math.random() * 2
                    }}
                  />
                ))}
              </div>
              
              {/* Horizontal scan line effect */}
              <motion.div 
                className="absolute h-px w-full bg-neural-400/30"
                style={{ boxShadow: '0 0 5px rgba(100, 200, 255, 0.3)' }}
                initial={{ top: '-10%', opacity: 0 }}
                animate={{ top: '110%', opacity: [0, 0.2, 0] }}
                transition={{
                  duration: 3,
                  repeat: Infinity,
                  repeatDelay: 8
                }}
              />
              
              {/* Vertical scan line effect */}
              <motion.div 
                className="absolute w-px h-full bg-neural-400/20"
                style={{ boxShadow: '0 0 3px rgba(100, 200, 255, 0.2)' }}
                initial={{ left: '-10%', opacity: 0 }}
                animate={{ left: '110%', opacity: [0, 0.15, 0] }}
                transition={{
                  duration: 4,
                  repeat: Infinity,
                  repeatDelay: 12,
                  delay: 2
                }}
              />
            </div>
            
            {/* Content */}
            <div className="py-4 px-3 sm:py-6 sm:px-6 text-center">
              {title && (
                <motion.h1 
                  className="text-2xl sm:text-3xl font-bold neural-text-gradient text-shadow-neural-glow mb-1"
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.5, delay: 0.2 }}
                >
                  {title}
                  <motion.span 
                    className="inline-block ml-1 w-1.5 h-4 bg-neural-400/90"
                    animate={{ opacity: [1, 0, 1] }}
                    transition={{ duration: 1, repeat: Infinity, repeatDelay: 0.5 }}
                  ></motion.span>
                </motion.h1>
              )}
              
              {subtitle && (
                <motion.p 
                  className="text-sm sm:text-lg text-neural-100/90"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.5, delay: 0.4 }}
                >
                  {subtitle}
                </motion.p>
              )}
              
              {/* Neural indicator dot with data transmission effect */}
              <div className="flex justify-center mt-2 sm:mt-3">
                <motion.div 
                  className="flex items-center neural-connector-line"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.3, delay: 0.6 }}
                >
                  <div className="relative">
                    <div className="w-1.5 sm:w-2 h-1.5 sm:h-2 rounded-full bg-neural-400 animate-pulse mr-1 sm:mr-2" />
                    <motion.div 
                      className="absolute top-1/2 left-1/2 w-3 sm:w-4 h-3 sm:h-4 -translate-x-1/2 -translate-y-1/2 rounded-full bg-neural-400/30"
                      animate={{ scale: [1, 1.5, 1], opacity: [0.3, 0.1, 0.3] }}
                      transition={{ duration: 2, repeat: Infinity }}
                    />
                  </div>
                  <div className="relative">
                    <motion.div
                      className="h-px w-8 sm:w-10 bg-neural-400/30 mr-2"
                      style={{ boxShadow: '0 0 2px rgba(100, 200, 255, 0.2)' }}
                    >
                      <motion.div 
                        className="absolute top-0 left-0 h-full w-1 bg-neural-400/80"
                        animate={{ x: [0, 32, 0] }}
                        transition={{ duration: 2, repeat: Infinity, repeatDelay: 1 }}
                      />
                    </motion.div>
                  </div>
                  <span className="text-xs text-neural-200 font-mono">NEURAL.INTERFACE.ACTIVE</span>
                </motion.div>
              </div>
            </div>
            
            {/* Bottom border with glow */}
            <div 
              className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-neural-400/30 to-transparent"
              style={{ boxShadow: '0 0 3px rgba(100, 200, 255, 0.3)' }}
            />
            
            {/* Side borders with glow */}
            <div 
              className="absolute top-0 bottom-0 left-0 w-px bg-gradient-to-b from-transparent via-neural-400/20 to-transparent"
              style={{ boxShadow: '0 0 2px rgba(100, 200, 255, 0.2)' }}
            />
            <div 
              className="absolute top-0 bottom-0 right-0 w-px bg-gradient-to-b from-transparent via-neural-400/20 to-transparent"
              style={{ boxShadow: '0 0 2px rgba(100, 200, 255, 0.2)' }}
            />
          </div>
        </motion.div>
      )}
      
      {/* Main content */}
      <motion.div variants={itemVariants} className="relative z-10">
        {children}
      </motion.div>
      
      {/* Neural connection glow effect at the bottom */}
      <div className="absolute bottom-0 left-0 right-0 h-16 sm:h-24 pointer-events-none">
        <div className="absolute inset-0 bg-gradient-to-t from-neural-400/5 to-transparent" />
      </div>
    </motion.div>
  );
};

export default NeuralPageWrapper; 