import React, { useState, useEffect, useRef } from 'react';
import { useTheme } from '../contexts/ThemeContext';
import { useAuth } from '../contexts/AuthContext';

// Import profile components
import ProfileInfo from '../components/profile/ProfileInfo';
import ProfileForm from '../components/profile/ProfileForm';
import StatsCard from '../components/profile/StatsCard';
import ThemeSettings from '../components/profile/ThemeSettings';
import NotificationSettings from '../components/profile/NotificationSettings';
import AchievementSection from '../components/profile/AchievementSection';

// Existing imports
import NeuralPageWrapper from '../components/NeuralPageWrapper';

// Neural network background components
const NeuralNode = ({ x, y, size, delay, color = 'rgba(100, 200, 255, 0.6)' }) => (
  <div 
    className="absolute rounded-full"
    style={{
      width: size,
      height: size,
      top: `${y}%`,
      left: `${x}%`,
      backgroundColor: color,
      filter: 'blur(1px)',
      opacity: 0.3
    }}
  />
);

const NeuralConnection = ({ startX, startY, endX, endY, active }) => {
  const pathData = `M ${startX} ${startY} L ${endX} ${endY}`;
  
  return (
    <svg className="absolute inset-0 w-full h-full pointer-events-none overflow-visible">
      <path 
        d={pathData}
        stroke="rgba(100, 200, 255, 0.4)"
        strokeOpacity={active ? 0.3 : 0.1}
        strokeWidth={active ? 1 : 0.5}
        fill="none"
        strokeDasharray={active ? "none" : "3,3"}
      />
    </svg>
  );
};

// SVG Avatar Component
const AvatarSVG = ({ seed, size = 100, gender = 'neutral', onClick, customImage }) => {
  // State for animations when clicked
  const [isAnimating, setIsAnimating] = useState(false);

  // Handle click animations
  const handleClick = () => {
    if (onClick) onClick();
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 1000);
  };

  // Memoize avatar generation to prevent unnecessary re-renders
  const avatarData = React.useMemo(() => {
    // Generate colors deterministically based on seed
    const getColor = (str, index) => {
      // Colors based on gender
      const colorSchemes = {
        male: ['#4F46E5', '#06B6D4', '#3B82F6', '#1D4ED8', '#2563EB'],
        female: ['#EC4899', '#F472B6', '#DB2777', '#BE185D', '#9D174D'],
        neutral: ['#10B981', '#059669', '#047857', '#065F46', '#064E3B']
      };

      const scheme = colorSchemes[gender] || colorSchemes.neutral;
      const charCode = str.charCodeAt(index % str.length);
      return scheme[charCode % scheme.length];
    };
    
    // Generate face colors based on gender
    const getFaceColor = (gender) => {
      switch(gender) {
        case 'male': return '#E5E7EB';
        case 'female': return '#FCE7F3';
        default: return '#D1FAE5';
      }
    };
    
    // Generate unique parts based on seed
    const seedStr = seed?.toString() || 'default';
    return {
      bgColor: getColor(seedStr, 0),
      faceColor: getFaceColor(gender),
      eyeColor: getColor(seedStr, 2),
      mouthColor: getColor(seedStr, 3),
      eyeType: seedStr.charCodeAt(0) % 3,
      mouthType: seedStr.charCodeAt(1) % 3,
      accessoryType: seedStr.charCodeAt(2) % 5, // More accessory options for fun
      expressionType: isAnimating ? Math.floor(Math.random() * 3) : -1, // Random expression when animating
    };
  }, [seed, gender, isAnimating]);

  // If there's a custom uploaded image, use that instead of SVG
  if (customImage) {
    return (
      <div className={`relative rounded-full overflow-hidden border-2 ${isAnimating ? 'animate-bounce' : ''}`} style={{ width: size, height: size }} onClick={handleClick}>
        <img 
          src={customImage} 
          alt="User avatar" 
          className="w-full h-full object-cover"
        />
      </div>
    );
  }
  
  // Simplified eyes with gender-specific variations
  const eyesElement = (() => {
    // If animating, show a surprised expression
    if (isAnimating) {
      return (
        <>
          <circle cx="35" cy="45" r="6" fill={avatarData.eyeColor} />
          <circle cx="65" cy="45" r="6" fill={avatarData.eyeColor} />
          <circle cx="35" cy="45" r="2" fill="white" />
          <circle cx="65" cy="45" r="2" fill="white" />
        </>
      );
    }

    // Normal eyes based on gender and type
    switch(avatarData.eyeType) {
      case 0:
        return (
          <>
            <circle cx="35" cy="45" r="5" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="5" fill={avatarData.eyeColor} />
            {gender === 'female' && (
              <>
                <path d="M25,40 Q35,35 45,40" stroke={avatarData.eyeColor} strokeWidth="1.5" fill="none" />
                <path d="M55,40 Q65,35 75,40" stroke={avatarData.eyeColor} strokeWidth="1.5" fill="none" />
              </>
            )}
          </>
        );
      case 1:
        return gender === 'male' ? (
          <>
            <rect x="30" y="40" width="10" height="8" rx="2" fill={avatarData.eyeColor} />
            <rect x="60" y="40" width="10" height="8" rx="2" fill={avatarData.eyeColor} />
          </>
        ) : (
          <>
            <path d="M30,45 Q35,40 40,45" stroke={avatarData.eyeColor} strokeWidth="2" fill="none" />
            <path d="M60,45 Q65,40 70,45" stroke={avatarData.eyeColor} strokeWidth="2" fill="none" />
            <circle cx="35" cy="45" r="2" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="2" fill={avatarData.eyeColor} />
          </>
        );
      default:
        return (
          <>
            <circle cx="35" cy="45" r="4" fill={avatarData.eyeColor} />
            <circle cx="65" cy="45" r="4" fill={avatarData.eyeColor} />
            <circle cx="35" cy="45" r="1" fill="white" />
            <circle cx="65" cy="45" r="1" fill="white" />
          </>
        );
    }
  })();
  
  // Mouth variations with expressions
  const mouthElement = (() => {
    // If animating, show a surprised mouth
    if (avatarData.expressionType === 0) {
      return <circle cx="50" cy="65" r="8" fill={avatarData.mouthColor} />;
    }
    
    if (avatarData.expressionType === 1) {
      return <path d="M30,65 Q50,85 70,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />;
    }
    
    if (avatarData.expressionType === 2) {
      return (
        <>
          <path d="M35,65 Q50,55 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
          <path d="M42,74 L58,74" stroke={avatarData.mouthColor} strokeWidth="2" />
        </>
      );
    }

    // Normal mouth based on type
    switch(avatarData.mouthType) {
      case 0:
        return <path d="M40,65 Q50,75 60,65" stroke={avatarData.mouthColor} strokeWidth="2" fill="none" />;
      case 1:
        return <rect x="40" y="65" width="20" height="6" rx="3" fill={avatarData.mouthColor} />;
      default:
        return gender === 'female' ? (
          <path d="M35,65 Q50,72 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
        ) : (
          <path d="M35,65 Q50,60 65,65" stroke={avatarData.mouthColor} strokeWidth="3" fill="none" />
        );
    }
  })();
  
  // Gender-specific accessories
  const accessoryElement = (() => {
    // Male-specific accessories
    if (gender === 'male') {
      switch(avatarData.accessoryType) {
        case 0:
          return <rect x="30" y="20" width="40" height="15" rx="5" fill="#4B5563" />; // Glasses
        case 1:
          return <path d="M25,25 L75,25 L75,30 L25,30 Z" fill="#1F2937" />; // Sunglasses
        case 2:
          return <path d="M30,15 Q50,5 70,15 L70,25 L30,25 Z" fill="#1F2937" />; // Hat
        default:
          return <path d="M25,30 L45,20 L55,20 L75,30" stroke="#1F2937" strokeWidth="2" fill="none" />; // Eyebrows
      }
    }
    
    // Female-specific accessories
    if (gender === 'female') {
      switch(avatarData.accessoryType) {
        case 0:
          return <path d="M20,30 Q50,10 80,30" stroke="#FFD700" strokeWidth="2" fill="none" />; // Crown
        case 1:
          return (
            <>
              <path d="M20,25 Q35,15 50,25 Q65,15 80,25" stroke="#FF69B4" strokeWidth="2" fill="none" />
              <circle cx="20" cy="25" r="3" fill="#FF69B4" />
              <circle cx="50" cy="25" r="3" fill="#FF69B4" />
              <circle cx="80" cy="25" r="3" fill="#FF69B4" />
            </>
          ); // Flower crown
        case 2:
          return <path d="M30,25 A20,10 0 0,1 70,25" stroke="#EC4899" strokeWidth="3" fill="none" />; // Hair band
        default:
          return (
            <>
              <circle cx="25" cy="30" r="5" fill="#9D174D" />
              <circle cx="75" cy="30" r="5" fill="#9D174D" />
            </>
          ); // Earrings
      }
    }
    
    // Neutral accessories
    switch(avatarData.accessoryType) {
      case 0:
        return <path d="M50,10 L60,25 L40,25 Z" fill="#047857" />; // Hat
      case 1:
        return <path d="M30,20 Q50,10 70,20" stroke="#047857" strokeWidth="2" fill="none" />; // Headband
      default:
        return null; // No accessory
    }
  })();
  
  return (
    <svg 
      width={size} 
      height={size} 
      viewBox="0 0 100 100" 
      xmlns="http://www.w3.org/2000/svg"
      onClick={handleClick}
      className={`cursor-pointer transition-all ${isAnimating ? 'scale-110' : ''}`}
    >
      {/* Background */}
      <circle cx="50" cy="50" r="50" fill={avatarData.bgColor} />
      
      {/* Face */}
      <circle cx="50" cy="50" r="35" fill={avatarData.faceColor} />
      
      {/* Eyes */}
      {eyesElement}
      
      {/* Mouth */}
      {mouthElement}
      
      {/* Accessory */}
      {accessoryElement}
      
      {/* Neural network overlay - animated when clicked */}
      <circle 
        cx="50" 
        cy="50" 
        r="48" 
        stroke="rgba(255,255,255,0.2)" 
        strokeWidth="0.5" 
        fill="none" 
        strokeDasharray="3,3"
        className={isAnimating ? 'animate-pulse' : ''}
      />
      
      {/* Subtle glow effect for fun */}
      {isAnimating && (
        <circle 
          cx="50" 
          cy="50" 
          r="52" 
          fill="none"
          stroke={avatarData.bgColor}
          strokeWidth="2"
          opacity="0.6"
        >
          <animate 
            attributeName="r" 
            from="52" 
            to="60" 
            dur="1s" 
            begin="0s" 
            fill="freeze" 
          />
          <animate 
            attributeName="opacity" 
            from="0.6" 
            to="0" 
            dur="1s" 
            begin="0s" 
            fill="freeze" 
          />
        </circle>
      )}
    </svg>
  );
};

const Profile = () => {
  const { theme } = useTheme();
  const { currentUser, updateUserData } = useAuth();
  const [editing, setEditing] = useState(false);
  const [customAvatar, setCustomAvatar] = useState(null);
  const [showAvatarOptions, setShowAvatarOptions] = useState(false);
  const [newUsername, setNewUsername] = useState('');
  const fileInputRef = useRef(null);
  
  // Neural background state - REDUCED NUMBER OF NODES
  const [nodes] = useState(() => {
    const nodeArray = [];
    for (let i = 0; i < 4; i++) { // Reduced from 8 to 4
      nodeArray.push({
        x: 10 + Math.random() * 80,
        y: 10 + Math.random() * 80,
        size: 3 + Math.random() * 3,
        delay: Math.random() * 2
      });
    }
    return nodeArray;
  });
  
  const [connections] = useState(() => {
    const connectionArray = [];
    for (let i = 0; i < 3; i++) { // Reduced from 6 to 3
      const sourceIndex = Math.floor(Math.random() * nodes.length);
      let targetIndex;
      do {
        targetIndex = Math.floor(Math.random() * nodes.length);
      } while (targetIndex === sourceIndex);
      
      connectionArray.push({
        startX: nodes[sourceIndex].x,
        startY: nodes[sourceIndex].y,
        endX: nodes[targetIndex].x,
        endY: nodes[targetIndex].y,
        active: i < 1 // Make fewer connections active
      });
    }
    return connectionArray;
  });
  
  // Initialize profile with empty values
  const [profile, setProfile] = useState({
    name: '',
    email: '',
    school: '',
    major: '',
    year: '',
    bio: '',
    gender: 'neutral',
    customAvatar: null
  });

  // Update profile data when user changes
  useEffect(() => {
    if (currentUser) {
      setProfile({
        name: currentUser.name || '',
        email: currentUser.email || '',
        school: currentUser.school || '',
        major: currentUser.major || '',
        year: currentUser.year || '',
        bio: currentUser.bio || '',
        gender: currentUser.gender || 'neutral',
        customAvatar: currentUser.customAvatar || null
      });
      
      // Set custom avatar if it exists
      if (currentUser.customAvatar) {
        setCustomAvatar(currentUser.customAvatar);
      }
      
      // Initialize new username with current name
      setNewUsername(currentUser.name || '');
    }
  }, [currentUser]);
  
  // Get user study data if available or empty arrays if not
  const studyData = currentUser && Array.isArray(currentUser.studyData) 
    ? currentUser.studyData 
    : [];
    
  const tasks = currentUser && Array.isArray(currentUser.tasks) 
    ? currentUser.tasks 
    : [];
  
  const handleProfileChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  // Handle avatar click to show options
  const handleAvatarClick = () => {
    setShowAvatarOptions(true);
  };
  
  // Handle file upload
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setCustomAvatar(imageData);
        // Update profile with custom avatar
        updateUserData({
          ...profile,
          customAvatar: imageData
        });
      };
      reader.readAsDataURL(file);
    }
    setShowAvatarOptions(false);
  };
  
  // Handle username change
  const handleUsernameChange = () => {
    if (newUsername.trim()) {
      updateUserData({
        ...profile,
        name: newUsername.trim()
      });
      setProfile(prev => ({
        ...prev,
        name: newUsername.trim()
      }));
    }
    setShowAvatarOptions(false);
  };
  
  // Handle changing gender
  const handleGenderChange = (gender) => {
    updateUserData({
      ...profile,
      gender,
      customAvatar: null // Reset custom avatar when changing gender
    });
    setProfile(prev => ({
      ...prev,
      gender,
      customAvatar: null
    }));
    setCustomAvatar(null);
    setShowAvatarOptions(false);
  };
  
  // Handle removing custom avatar
  const handleResetAvatar = () => {
    setCustomAvatar(null);
    updateUserData({
      ...profile,
      customAvatar: null
    });
    setShowAvatarOptions(false);
  };
  
  const handleSubmit = (e) => {
    e.preventDefault();
    setEditing(false);
    
    if (currentUser) {
      // Use the auth context's update function instead of directly manipulating localStorage
      updateUserData({
        ...profile,
        // Ensure these arrays are preserved
        studyData: currentUser.studyData || [],
        tasks: currentUser.tasks || []
      });
    }
  };
  
  // Simplify loading animation
  if (!currentUser) {
    return (
      <NeuralPageWrapper title="Loading Profile...">
        <div className="flex justify-center items-center h-screen">
          <div className="text-white flex flex-col items-center">
            <div className="w-16 h-16 border-4 border-t-transparent border-blue-500 rounded-full animate-spin mb-4" />
            Loading profile data...
          </div>
        </div>
      </NeuralPageWrapper>
    );
  }
  
  return (
    <NeuralPageWrapper title="Neural Profile">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        {/* Neural Grid Layout */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          
          {/* Left Column - Profile & Stats */}
          <div className="lg:col-span-1 space-y-6">
            {/* Profile Avatar Card */}
            <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
              {/* Neural background - simplified */}
              <div className="absolute inset-0 overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-neural-400/30 to-neural-600/20 opacity-30" />
                <div 
                  className="absolute inset-0 opacity-10"
                  style={{ 
                    backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                     linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                    backgroundSize: '20px 20px'
                  }} 
                />
                
                {/* Only show 2 nodes */}
                {nodes.slice(0, 2).map((node, i) => (
                  <NeuralNode
                    key={`avatar-node-${i}`}
                    x={node.x}
                    y={node.y}
                    size={node.size}
                    delay={node.delay}
                  />
                ))}
                
                {/* Only show 1 connection */}
                {connections.slice(0, 1).map((conn, i) => (
                  <NeuralConnection
                    key={`avatar-conn-${i}`}
                    startX={conn.startX}
                    startY={conn.startY}
                    endX={conn.endX}
                    endY={conn.endY}
                    active={conn.active}
                  />
                ))}
              </div>
              
              <div className="relative z-10 p-6 flex flex-col items-center">
                <div className="w-24 h-24 mb-4 relative">
                  {/* SVG Avatar with gender and custom image support */}
                  <AvatarSVG 
                    seed={profile.email} 
                    size={100} 
                    gender={profile.gender}
                    onClick={handleAvatarClick}
                    customImage={customAvatar}
                  />
                  
                  {/* Small edit icon */}
                  <div 
                    className="absolute bottom-0 right-0 bg-neural-600 p-1 rounded-full cursor-pointer border border-neural-400/30 shadow-lg z-20"
                    onClick={handleAvatarClick}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" viewBox="0 0 20 20" fill="currentColor">
                      <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                    </svg>
                  </div>
                  
                  {/* Avatar options modal */}
                  {showAvatarOptions && (
                    <div className="fixed inset-0 flex items-center justify-center z-50 bg-black/70">
                      <div className={`${theme.card.background} p-6 rounded-xl max-w-md w-full shadow-xl border border-neural-400/30`}>
                        <h3 className={`text-xl font-bold ${theme.text.primary} mb-4`}>
                          Customize Your Avatar
                        </h3>
                        
                        {/* Upload photo option */}
                        <div className="mb-4">
                          <p className={`text-sm ${theme.text.secondary} mb-2`}>Upload your photo</p>
                          <input 
                            type="file" 
                            onChange={handleFileUpload} 
                            accept="image/*" 
                            className="hidden"
                            ref={fileInputRef}
                          />
                          <button
                            onClick={() => fileInputRef.current.click()}
                            className="w-full py-2 px-4 bg-neural-600 hover:bg-neural-500 text-white rounded-lg text-sm mb-2"
                          >
                            Choose Photo
                          </button>
                          
                          {customAvatar && (
                            <button
                              onClick={handleResetAvatar}
                              className="w-full py-2 px-4 bg-red-600/30 hover:bg-red-600/50 text-white rounded-lg text-sm"
                            >
                              Remove Photo
                            </button>
                          )}
                        </div>
                        
                        {/* Change username */}
                        <div className="mb-4">
                          <p className={`text-sm ${theme.text.secondary} mb-2`}>Change username</p>
                          <div className="flex space-x-2">
                            <input
                              type="text"
                              value={newUsername}
                              onChange={(e) => setNewUsername(e.target.value)}
                              className="flex-1 neural-input text-white/90 text-sm py-2"
                              placeholder="New username"
                            />
                            <button
                              onClick={handleUsernameChange}
                              className="py-2 px-4 bg-neural-600 hover:bg-neural-500 text-white rounded-lg text-sm"
                            >
                              Save
                            </button>
                          </div>
                        </div>
                        
                        {/* Choose avatar style */}
                        <div className="mb-6">
                          <p className={`text-sm ${theme.text.secondary} mb-2`}>Choose avatar style</p>
                          <div className="grid grid-cols-3 gap-3">
                            <div 
                              className={`p-2 rounded-lg flex flex-col items-center cursor-pointer ${profile.gender === 'male' ? 'bg-blue-500/20 border border-blue-500/30' : 'hover:bg-neural-700/50'}`}
                              onClick={() => handleGenderChange('male')}
                            >
                              <AvatarSVG seed={profile.email} size={60} gender="male" />
                              <span className={`text-xs mt-1 ${theme.text.secondary}`}>Male</span>
                            </div>
                            <div 
                              className={`p-2 rounded-lg flex flex-col items-center cursor-pointer ${profile.gender === 'female' ? 'bg-pink-500/20 border border-pink-500/30' : 'hover:bg-neural-700/50'}`}
                              onClick={() => handleGenderChange('female')}
                            >
                              <AvatarSVG seed={profile.email} size={60} gender="female" />
                              <span className={`text-xs mt-1 ${theme.text.secondary}`}>Female</span>
                            </div>
                            <div 
                              className={`p-2 rounded-lg flex flex-col items-center cursor-pointer ${profile.gender === 'neutral' ? 'bg-green-500/20 border border-green-500/30' : 'hover:bg-neural-700/50'}`}
                              onClick={() => handleGenderChange('neutral')}
                            >
                              <AvatarSVG seed={profile.email} size={60} gender="neutral" />
                              <span className={`text-xs mt-1 ${theme.text.secondary}`}>Neutral</span>
                            </div>
                          </div>
                        </div>
                        
                        {/* Close button */}
                        <button
                          onClick={() => setShowAvatarOptions(false)}
                          className="w-full py-2 bg-neural-700/50 hover:bg-neural-700 text-white rounded-lg text-sm"
                        >
                          Close
                        </button>
                      </div>
                    </div>
                  )}
                  
                  {/* Glow effect */}
                  <div className="absolute inset-0 rounded-full bg-blue-500 opacity-20 blur-lg -z-10"></div>
                </div>
                
                <h2 className={`text-xl font-bold ${theme.text.primary} mb-1`}>
                  {profile.name || 'Neural User'}
                </h2>
                <p className={`text-sm ${theme.text.secondary} mb-4`}>
                  {profile.major ? `${profile.major} Student` : 'Student'}
                </p>
                
                <button
                  onClick={() => setEditing(true)}
                  className="px-4 py-2 rounded-lg bg-neural-600 hover:bg-neural-500 text-white text-sm transition-all duration-200 shadow-glow-sm"
                >
                  Edit Profile
                </button>
              </div>
            </div>
                    
            {/* Stats Card with neural background - simplified */}
            <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
              {/* Neural background - simplified */}
              <div className="absolute inset-0 overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-br from-neural-400/30 to-neural-600/20 opacity-30" />
                <div 
                  className="absolute inset-0 opacity-10"
                  style={{ 
                    backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                     linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                    backgroundSize: '20px 20px'
                  }} 
                />
                
                {/* Only show 2 nodes */}
                {nodes.slice(2, 4).map((node, i) => (
                  <NeuralNode
                    key={`stats-node-${i}`}
                    x={node.x}
                    y={node.y}
                    size={node.size}
                    delay={node.delay}
                  />
                ))}
                
                {/* Only show 1 connection */}
                {connections.slice(1, 2).map((conn, i) => (
                  <NeuralConnection
                    key={`stats-conn-${i}`}
                    startX={conn.startX}
                    startY={conn.startY}
                    endX={conn.endX}
                    endY={conn.endY}
                    active={conn.active}
                  />
                ))}
              </div>
              
              <StatsCard 
                studyData={studyData} 
                tasks={tasks} 
              />
            </div>
          </div>
          
          {/* Center/Right Columns - Main Content - simplified */}
          <div className="lg:col-span-3 space-y-6">
            {/* Profile Info Card */}
            <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
              {/* Neural background - simplified */}
              <div className="absolute inset-0 overflow-hidden opacity-50">
                <div 
                  className="absolute inset-0 opacity-10"
                  style={{ 
                    backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                     linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                    backgroundSize: '20px 20px'
                  }} 
                />
              </div>
              
              <div className="relative z-10">
                {editing ? (
                  <ProfileForm 
                    profile={profile}
                    onChange={handleProfileChange}
                    onSubmit={handleSubmit}
                    onCancel={() => setEditing(false)}
                  />
                ) : (
                  <ProfileInfo 
                    profile={profile} 
                    onEdit={() => setEditing(true)} 
                  />
                )}
              </div>
            </div>
            
            {/* Settings Cards */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Theme Settings Card */}
              <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
                <div className="absolute inset-0 overflow-hidden opacity-30">
                  <div 
                    className="absolute inset-0 opacity-10"
                    style={{ 
                      backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                       linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                      backgroundSize: '20px 20px'
                    }} 
                  />
                </div>
                
                <div className="relative z-10">
                  <ThemeSettings />
                </div>
              </div>
              
              {/* Notification Settings Card */}
              <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
                <div className="absolute inset-0 overflow-hidden opacity-30">
                  <div 
                    className="absolute inset-0 opacity-10"
                    style={{ 
                      backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                       linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                      backgroundSize: '20px 20px'
                    }} 
                  />
                </div>
                
                <div className="relative z-10">
                  <NotificationSettings />
                </div>
              </div>
            </div>
            
            {/* Achievement Section */}
            <div className={`${theme.card.background} rounded-xl overflow-hidden shadow-neural relative border border-neural-400/20`}>
              <div className="absolute inset-0 overflow-hidden opacity-30">
                <div 
                  className="absolute inset-0 opacity-10"
                  style={{ 
                    backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                     linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                    backgroundSize: '20px 20px'
                  }} 
                />
                
                {/* Only show 1 node, no animation */}
                {nodes.slice(0, 1).map((node, i) => (
                  <NeuralNode
                    key={`achieve-node-${i}`}
                    x={node.x}
                    y={node.y}
                    size={node.size}
                    delay={node.delay}
                  />
                ))}
              </div>
              
              <div className="relative z-10">
                <AchievementSection />
              </div>
            </div>
          </div>
        </div>
      </div>
    </NeuralPageWrapper>
  );
};

export default Profile; 