import React from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../../contexts/ThemeContext';
import { useAuth } from '../../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';

const ProfileInfo = ({ profile, onEdit }) => {
  const { theme } = useTheme();
  const { logout, currentUser } = useAuth();
  const navigate = useNavigate();
  
  const handleLogout = () => {
    logout();
    navigate('/login');
  };
  
  return (
    <>
      <div className="flex justify-between items-center mb-4">
        <motion.h3 
          className={`text-xl font-bold ${theme.text.primary}`}
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.2 }}
        >
          Personal Information
        </motion.h3>
        <div className="flex space-x-2">
          <motion.button
            className={`px-3 py-1.5 ${theme.button.primary} flex items-center rounded-lg`}
            whileHover={{ 
              scale: 1.05,
              boxShadow: theme.animation.glow
            }}
            whileTap={{ scale: 0.95 }}
            onClick={onEdit}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
              <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
            </svg>
            Edit
          </motion.button>
          
          <motion.button
            className={`px-3 py-1.5 bg-red-500/20 border border-red-500/30 text-red-300 flex items-center rounded-lg`}
            whileHover={{ 
              scale: 1.05,
              boxShadow: '0 0 15px rgba(220, 38, 38, 0.4)'
            }}
            whileTap={{ scale: 0.95 }}
            onClick={handleLogout}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M3 3a1 1 0 00-1 1v12a1 1 0 001 1h12a1 1 0 001-1V7.414l-5-5H3zm1 2h6v4h4v6H4V5z" clipRule="evenodd" />
              <path d="M14 7V5.5a.5.5 0 01.5-.5h2a.5.5 0 01.5.5V8a.5.5 0 01-.5.5H14a.5.5 0 01-.5-.5V7z" />
              <path fillRule="evenodd" d="M10 10a.5.5 0 01.5.5v4a.5.5 0 01-1 0v-4a.5.5 0 01.5-.5z" clipRule="evenodd" />
              <path d="M12.707 12.707a.5.5 0 01-.707 0L10 10.707l-2 2a.5.5 0 01-.707-.707l2-2a.5.5 0 01.707 0l2 2a.5.5 0 010 .707z" />
            </svg>
            Logout
          </motion.button>
        </div>
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <p className={`text-sm ${theme.text.muted}`}>School</p>
          <p className={`${theme.text.primary} font-medium`}>{profile.school}</p>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
        >
          <p className={`text-sm ${theme.text.muted}`}>Major</p>
          <p className={`${theme.text.primary} font-medium`}>{profile.major}</p>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
        >
          <p className={`text-sm ${theme.text.muted}`}>Year</p>
          <p className={`${theme.text.primary} font-medium`}>{profile.year}</p>
        </motion.div>
        
        {currentUser && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5 }}
          >
            <p className={`text-sm ${theme.text.muted}`}>Email</p>
            <p className={`${theme.text.primary} font-medium`}>{currentUser.email}</p>
          </motion.div>
        )}
      </div>
      
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.6 }}
      >
        <p className={`text-sm ${theme.text.muted} mb-1`}>Bio</p>
        <p className={`${theme.text.secondary} leading-relaxed`}>{profile.bio}</p>
      </motion.div>
    </>
  );
};

export default ProfileInfo; 